+      }
+
+      .intro {
+        margin: 1rem 0 1.75rem;
+        color: var(--muted);
+      }
+
+      .form-field {
+        display: grid;
+        grid-template-columns: auto 1fr;
+        gap: 0.25rem 0.875rem;
+        border: 0.0625rem solid var(--panel-border);
+        border-radius: 1rem;
+        background: #0f172a;
+        padding: 1rem;
+      }
+
+      .form-field input {
+        width: 1.25rem;
+        height: 1.25rem;
+        margin: 0.125rem 0 0;
+        accent-color: var(--accent-dark);
+      }
+
+      .form-field label {
+        color: var(--text);
+        font-weight: 700;
+      }
+
+      .helper-text {
+        grid-column: 2;
+        margin: 0;
+        color: var(--muted);
+        font-size: 0.9375rem;
+      }
+
+      button {
+        width: 100%;
+        margin-top: 1.25rem;
+        border: 0;
+        border-radius: 999px;
+        background: linear-gradient(135deg, var(--accent), #5eead4);
+        color: var(--button-text);
+        cursor: pointer;
+        font: inherit;
+        font-weight: 800;
+        padding: 0.875rem 1.25rem;
+        transition: transform 160ms ease, box-shadow 160ms ease;
+      }
+
+      button:hover {
+        box-shadow: 0 0.75rem 1.5rem rgb(34 197 94 / 25%);
+        transform: translateY(-0.0625rem);
+      }
+
+      button:active {
+        transform: translateY(0);
+      }
+
+      input:focus-visible,
+      button:focus-visible {
+        outline: 0.1875rem solid var(--focus);
+        outline-offset: 0.1875rem;
+      }
+
+      .status {
+        min-height: 1.5rem;
+        margin: 1rem 0 0;
+        color: var(--accent);
+        font-weight: 700;
+      }
+
+      .status.error {
+        color: var(--error);
+      }
+
