        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main">Skip to main content</a>
    <main id="main"></main>

    <script>
      const ConsentForm = () => `
        <section class="consent-card" aria-labelledby="form-title">
          <p class="eyebrow">Account setup</p>
          <h1 id="form-title">Review and agree</h1>
          <p class="intro">Confirm your consent before continuing.</p>
          <form id="terms-form" novalidate>
            <div class="form-field">
              <input
                type="checkbox"
                id="terms-consent"
                name="termsConsent"
                aria-describedby="terms-helper"
                required
              >
              <label for="terms-consent">I agree to the terms of use</label>
              <p class="helper-text" id="terms-helper">Required to create or continue using your account.</p>
              <p class="error-text" id="terms-error" hidden>Please agree to the terms of use before submitting.</p>
            </div>
            <button type="submit">Submit agreement</button>
            <p class="status" id="form-status" aria-live="polite"></p>
          </form>
        </section>
      `;

      const App = () => ConsentForm();

      document.querySelector("#main").innerHTML = App();

      const form = document.querySelector("#terms-form");
      const checkbox = document.querySelector("#terms-consent");
      const error = document.querySelector("#terms-error");
      const status = document.querySelector("#form-status");

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        if (!checkbox.checked) {
          checkbox.setAttribute("aria-invalid", "true");
          checkbox.setAttribute("aria-describedby", "terms-helper terms-error");
          error.hidden = false;
          status.textContent = "";
          checkbox.focus();
          return;
        }

        checkbox.removeAttribute("aria-invalid");
        checkbox.setAttribute("aria-describedby", "terms-helper");
        error.hidden = true;
        status.textContent = "Agreement submitted.";
      });

      checkbox.addEventListener("change", () => {
        if (checkbox.checked) {
          checkbox.removeAttribute("aria-invalid");
          checkbox.setAttribute("aria-describedby", "terms-helper");
          error.hidden = true;
          status.textContent = "";
        }
      });
    </script>
  </body>
</html>
